package peony.patchs;

import java.util.Iterator;
import java.util.List;

import peony.game.ObjectAccessor;
import peony.game.skill.Skill;

public class SkillPatch implements Runnable {

	public void run() {
		
		List<Skill>[] ss = ObjectAccessor.playerInitSkills;
		for(int i=0;i<ss.length;i++){
			List<Skill> l = ss[i];
			if(l!=null){
				Iterator<Skill> ite = l.iterator();
				while(ite.hasNext()){
					Skill skill = ite.next();
					if(skill.getGroupId()==175){
						ite.remove();
						System.out.println("skill removed");
						break;
					}
				}
			}
		}

//		for(int j=0;j<AutoGeneratedSkill_175.MP_USE.length;j++){
//			AutoGeneratedSkill_175.MP_USE[j] = 9999999f;
//		}
//		System.out.println("skill modified");
	}

}
